pub fn find_named_child(root: Rc<Node>, name: String) -> Rc<Outcome<Rc<Node>>> {
    match (*root.kind.clone()).clone() {
        NodeKind::TypeNode { ref connective, .. }
            if matches!(connective.as_ref(), Connective::Conj) =>
        {
            let Connective::Conj = connective.as_ref() else {
                unreachable!()
            };
            {
                let count = name_occurrences(name.clone(), root.children.clone());
                if (count.clone() == 1) {
                    root.children.clone().iter().cloned().fold(
                        outcome_rejected(Rc::new(Diagnostic {
                            reason: "named_child_missing".to_string(),
                            at: node_locus(root.clone()),
                            correction: Rc::new(Correction::Unavailable {
                                reason: NoCorrectionReason::ExternalContractUnknown,
                            }),
                        })),
                        |acc: _, e: Rc<Edge>| match acc.clone() {
                            Outcome::Accepted { .. } => acc.clone(),
                            Outcome::Rejected { diagnostics: _, .. } => {
                                match (*e.label.clone()).clone() {
                                    EdgeLabel::Named {
                                        name: edge_name, ..
                                    } => {
                                        if (edge_name.clone() == name.clone()) {
                                            outcome_accepted(e.target.clone())
                                        } else {
                                            acc.clone()
                                        }
                                    }
                                    EdgeLabel::Positional => acc.clone(),
                                }
                            }
                        },
                    )
                } else {
                    if (count.clone() == 0) {
                        outcome_rejected(Rc::new(Diagnostic {
                            reason: "named_child_missing".to_string(),
                            at: node_locus(root.clone()),
                            correction: Rc::new(Correction::Unavailable {
                                reason: NoCorrectionReason::ExternalContractUnknown,
                            }),
                        }))
                    } else {
                        outcome_rejected(Rc::new(Diagnostic {
                            reason: "named_child_ambiguous".to_string(),
                            at: node_locus(root.clone()),
                            correction: Rc::new(Correction::Unavailable {
                                reason: NoCorrectionReason::ExternalContractUnknown,
                            }),
                        }))
                    }
                }
            }
        }
        _ => outcome_rejected(Rc::new(Diagnostic {
            reason: "named_child_missing".to_string(),
            at: node_locus(root.clone()),
            correction: Rc::new(Correction::Unavailable {
                reason: NoCorrectionReason::ExternalContractUnknown,
            }),
        })),
    }
}

