pub fn conj_ordered_named_param_binding_ids(domain: Rc<Node>) -> Rc<Outcome<Rc<Vec<String>>>> {
    match (*domain.kind.clone()).clone() {
        NodeKind::TypeNode { ref connective, .. }
            if matches!(connective.as_ref(), Connective::Conj) =>
        {
            let Connective::Conj = connective.as_ref() else {
                unreachable!()
            };
            match domain.children.clone().iter().cloned().fold(
                outcome_accepted(Rc::new(vec![])),
                |acc: _, edge: Rc<Edge>| match acc.clone() {
                    Outcome::Accepted {
                        value: bindings,
                        diagnostics: d,
                        ..
                    } => match (*edge.label.clone()).clone() {
                        EdgeLabel::Named { name: sym, .. } => outcome_with_diagnostics(
                            list_snoc_item(bindings.clone(), sym.clone()),
                            d.clone(),
                        ),
                        EdgeLabel::Positional => {
                            outcome_rejected(node_query_domain_malformed_diagnostic(domain.clone()))
                        }
                    },
                    Outcome::Rejected { diagnostics: _, .. } => acc.clone(),
                },
            ) {
                Outcome::Accepted {
                    value: bindings,
                    diagnostics: d,
                    ..
                } => {
                    if crate::v2_std_algebra::is_empty(bindings.clone()) {
                        outcome_rejected(node_query_domain_malformed_diagnostic(domain.clone()))
                    } else {
                        outcome_with_diagnostics(bindings.clone(), d.clone())
                    }
                }
                Outcome::Rejected { diagnostics: d, .. } => Rc::new(Outcome::Rejected {
                    diagnostics: d.clone(),
                }),
            }
        }
        _ => outcome_rejected(node_query_domain_malformed_diagnostic(domain.clone())),
    }
}

